#include "modules/cas_api.h"
#include "algebra/pentarnion.hpp"
#include <nlohmann/json.hpp>
#include <array>
#include <cmath>
#include <complex>
#include <iostream>
#include <vector>
namespace {
using Json=nlohmann::json;
int checks=0,failures=0;
void expect(bool okay,const char* text){++checks;if(!okay){++failures;std::cerr<<"FAIL: "<<text<<'\n';}}
struct Host {bool cancelled=false;std::size_t work=0;static int cancel(void* raw){return static_cast<Host*>(raw)->cancelled;}static int charge(void* raw,uint64_t amount,char*,uint64_t){static_cast<Host*>(raw)->work+=amount;return 0;}};
Json call(const Json& input,int expected=0,uint64_t maximum=10000000,bool cancel=false){Host host;host.cancelled=cancel;penta_cas_host_v1 h{sizeof(h),PENTA_CAS_ABI_V1,&host,Host::cancel,Host::charge};const auto text=input.dump();std::vector<char> output(4*1024*1024+1);penta_cas_request_v1 request{sizeof(request),text.c_str(),text.size(),maximum,output.data(),output.size()};char error[2048]{};const auto status=penta_cas_query_v1(PENTA_CAS_ABI_V1)->execute(&h,&request,error,sizeof(error));expect(status==expected,"Native CAS status agrees with its contract.");if(status!=expected)std::cerr<<error<<'\n';if(status)return {};expect(host.work>0,"Native symbolic operations report charged work.");return Json::parse(output.data());}
Json scalar(const std::string& text,Json options=Json::object()){return call({{"operation","cas"},{"expression",text},{"settings",options}});}
std::complex<double> number(const Json& value,Json bindings=Json::object()){const auto result=call({{"operation","casnumeric"},{"value",value},{"bindings",bindings}});return {result["values"][0][0].get<double>(),result["values"][0][1].get<double>()};}
}
int main(){try{
    const auto polynomial=scalar("x^3+sin(x)+exp(x)",{{"symbols","x"}});const auto derivative=call({{"operation","casdiff"},{"value",polynomial},{"variable","x"}});expect(std::abs(number(derivative,{{"x",{.3,0}}}).real()-(3*.3*.3+std::cos(.3)+std::exp(.3)))<1e-12,"Symbolic product/chain rules agree with an independent derivative.");
    const auto rational=scalar("1/x",{{"symbols","x"},{"nonzero","x"}});const auto rationalDerivative=call({{"operation","casdiff"},{"value",rational},{"variable","x"}});expect(std::abs(number(rationalDerivative,{{"x",{2,0}}}).real()+.25)<1e-12,"Explicit variable denominators differentiate correctly.");call({{"operation","cas"},{"expression","1/x"},{"settings",{{"symbols","x"}}}},1);call({{"operation","cassubs"},{"value",rational},{"variable","x"},{"replacement","0"}},2);
    const auto formal=scalar("f(x)",{{"symbols","x"},{"functions","f"}});const auto formalDerivative=call({{"operation","casdiff"},{"value",formal},{"variable","x"}});expect(formalDerivative["entries"][0].get<std::string>().find("f__d1")!=std::string::npos,"Declared central formal functions retain explicit derivative functions.");
    const auto complex=scalar("sqrt(-1)",{{"domain","complex"}});expect(std::abs(number(complex)-std::complex<double>(0,1))<1e-12,"Complex radical domain uses the principal complex square root.");call({{"operation","cas"},{"expression","sqrt(-1)"},{"settings",Json::object()}},2);
    call({{"operation","cas"},{"expression","x"},{"settings",{{"symbols","x"},{"nonzero","0"}}}},2);call({{"operation","cas"},{"expression","x"},{"settings",{{"symbols","x"},{"positive","-1"}}}},2);
    const auto product=call({{"operation","caspent"},{"expression","i*j"},{"settings",{{"gamma","symbolic"}}}});for(double gamma:{0.,.3,1.}){const auto values=call({{"operation","casnumeric"},{"value",product},{"bindings",{{"gamma",{gamma,0}}}}});const penta::algebra::Context c(gamma);const auto reference=penta::algebra::multiply(penta::algebra::Pentarnion::basis(c,1),penta::algebra::Pentarnion::basis(c,2));bool same=true;for(unsigned n=0;n<5;++n)same=same&&std::abs(values["values"][n][0].get<double>()-reference.coefficients()[n])<1e-12;expect(same,"Variable-gamma symbolic table agrees with the published numeric multiplication table.");}
    const auto gammaDerivative=call({{"operation","casdiff"},{"value",product},{"variable","gamma"}});const auto d=call({{"operation","casnumeric"},{"value",gammaDerivative},{"bindings",{{"gamma",{.4,0}}}}});expect(std::abs(d["values"][3][0].get<double>()+.4/std::pow(1.16,1.5))<1e-12&&std::abs(d["values"][4][0].get<double>()-1/std::pow(1.16,1.5))<1e-12,"Symbolic gamma differentiates normalization and mixing coefficients analytically.");
    const auto bracketed=call({{"operation","caspent"},{"expression","(p*q)*r-p*(q*r)"},{"pentarnions","p,q,r"},{"settings",{{"gamma","symbolic"}}}});Json basisBindings{{"gamma",{1,0}}};for(const auto* name:{"p","q","r"})for(unsigned n=0;n<5;++n)basisBindings[std::string(name)+std::to_string(n)]={0,0};basisBindings["p1"]={1,0};basisBindings["q2"]={1,0};basisBindings["r4"]={1,0};const auto bracketValues=call({{"operation","casnumeric"},{"value",bracketed},{"bindings",basisBindings}});const penta::algebra::Context one(1);const auto association=penta::algebra::associator(penta::algebra::Pentarnion::basis(one,1),penta::algebra::Pentarnion::basis(one,2),penta::algebra::Pentarnion::basis(one,4));bool sameBracket=true;for(unsigned n=0;n<5;++n)sameBracket=sameBracket&&std::abs(bracketValues["values"][n][0].get<double>()-association.coefficients()[n])<1e-12;expect(sameBracket,"Symbolic polynomial expansion preserves distinct nonassociative bracketings.");
    call({{"operation","caspent"},{"expression","p*q*r"},{"pentarnions","p,q,r"},{"settings",Json::object()}},1);
    const Json settings{{"symbols","a"}};const auto A=call({{"operation","casmatrix"},{"expression","a,1;1,1"},{"settings",settings}}),B=call({{"operation","casmatrix"},{"expression","1;0"},{"settings",settings}});const auto X=call({{"operation","caslinsolve"},{"value",A},{"other",B}});expect(!X["nonzero"].get<std::string>().empty(),"Symbolic elimination retains its conditional nonzero pivot domain.");const auto solution=call({{"operation","casnumeric"},{"value",X},{"bindings",{{"a",{3,0}}}}});expect(std::abs(solution["values"][0][0].get<double>()-.5)<1e-12&&std::abs(solution["values"][1][0].get<double>()+.5)<1e-12,"Conditional symbolic matrix solve agrees with independent linear equations.");call({{"operation","casnumeric"},{"value",X},{"bindings",{{"a",{1,0}}}}},2);
    const auto determinant=call({{"operation","casdet"},{"value",A}});expect(number(determinant,{{"a",{3,0}}}).real()==2,"Symbolic determinant preserves exact central coefficient algebra.");
    call({{"operation","cas"},{"expression","x*x"},{"settings",{{"symbols","x"}}}},7,1);call({{"operation","cas"},{"expression","1"},{"settings",Json::object()}},PENTA_NUMERIC_CANCELLED,100,true);
}catch(const std::exception& error){++failures;std::cerr<<error.what()<<'\n';}std::cout<<checks<<" native CAS kernel checks, "<<failures<<" failures\n";return failures?1:0;}
